<?php defined('C5_EXECUTE') or die('Access Denied.');
$app=\Concrete\Core\Support\Facade\Application::getFacadeApplication();
$csrf=(string)$app->make('helper/validation/token')->generate('xavi_sky_action');
?>
<style>
html:has(#xavi-sky-app),html:has(#xavi-sky-app) body{background:#000;color:#fff;width:100%;max-width:none;overflow-x:hidden}
html:has(#xavi-sky-app) .ccm-page:has(#xavi-sky-app),html:has(#xavi-sky-app) main:has(#xavi-sky-app),html:has(#xavi-sky-app) .container:has(#xavi-sky-app),html:has(#xavi-sky-app) .container-fluid:has(#xavi-sky-app),html:has(#xavi-sky-app) .row:has(#xavi-sky-app),html:has(#xavi-sky-app) [class^="col-"]:has(#xavi-sky-app){width:100%!important;max-width:none!important;margin:0!important;padding-left:0!important;padding-right:0!important}
#xavi-sky-app{font:14px/1.4 ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;background:#000;color:#fff;min-height:70vh;width:100dvw;margin-left:calc(50% - 50dvw);padding:14px;box-sizing:border-box}
#xavi-sky-app *{box-sizing:border-box}.xs-head{display:flex;gap:12px;align-items:center;flex-wrap:wrap;border:1px solid #fff;padding:10px;margin-bottom:10px}.xs-head h1{font-size:20px;margin:0}.xs-muted{opacity:.7}.xs-spacer{flex:1}.xs-btn,.xs-in{background:#000;color:#fff;border:1px solid #fff;border-radius:0;padding:7px 9px}.xs-btn{cursor:pointer}.xs-btn:disabled{opacity:.45;cursor:not-allowed}.xs-grid{display:grid;grid-template-columns:repeat(6,minmax(130px,1fr));gap:8px;margin-bottom:10px}.xs-card,.xs-panel{border:1px solid #fff;background:#000}.xs-card{padding:10px}.xs-card b{display:block;font-size:22px}.xs-tabs{display:flex;gap:0;margin-bottom:8px;flex-wrap:wrap}.xs-tab{border:1px solid #fff;background:#000;color:#fff;padding:7px 12px;cursor:pointer;margin-right:-1px}.xs-tab.on{background:#fff;color:#000}.xs-panel{overflow:auto}.xs-panel table{width:100%;border-collapse:collapse;min-width:1100px}.xs-panel th,.xs-panel td{border-bottom:1px solid #333;padding:7px 8px;text-align:left;vertical-align:top}.xs-panel th{position:sticky;top:0;background:#000;border-bottom:1px solid #fff}.xs-score{font-variant-numeric:tabular-nums}.xs-good{font-weight:700}.xs-bad{opacity:.65}.xs-json{white-space:pre-wrap;max-width:520px;word-break:break-word}.xs-search{display:flex;gap:8px;margin:0 0 8px}.xs-error{border:1px solid #fff;padding:10px;margin-bottom:10px}.xs-node-live::before{content:'● ';}.xs-node-stale{opacity:.55}.xs-actions{display:flex;gap:5px;flex-wrap:wrap}.xs-link{color:#fff}@media(max-width:900px){.xs-grid{grid-template-columns:repeat(2,1fr)}}
</style>
<div id="xavi-sky-app"><div class="xs-head"><h1>Xavi-Sky</h1><span class="xs-muted">federated Bluesky discovery / ranking / dedupe</span><span class="xs-muted">writes require an explicit Follow click</span><span class="xs-spacer"></span><span id="xs-refresh-state" class="xs-muted">loading…</span><button class="xs-btn" id="xs-refresh">Refresh</button></div><div id="xs-error"></div><div class="xs-grid" id="xs-cards"></div><div class="xs-tabs"><button class="xs-tab on" data-tab="nodes">Nodes</button><button class="xs-tab" data-tab="candidates">Candidates</button><button class="xs-tab" data-tab="packs">Starter Packs</button><button class="xs-tab" data-tab="events">Event Log</button></div><div class="xs-search"><input id="xs-q" class="xs-in" placeholder="filter candidates"><button id="xs-search" class="xs-btn">Search</button></div><div class="xs-panel" id="xs-panel"><div style="padding:12px">Loading…</div></div></div>
<script>
(()=>{
const CSRF=<?=json_encode($csrf,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>;
const A={status:'/api/xavi/sky/status',nodes:'/api/xavi/sky/nodes',events:'/api/xavi/sky/events',candidates:'/api/xavi/sky/candidates',packs:'/api/xavi/sky/starter-packs',accounts:'/api/xavi/sky/accounts',follow:'/api/xavi/sky/follow'};
const panel=document.getElementById('xs-panel'),err=document.getElementById('xs-error'),cards=document.getElementById('xs-cards'),state=document.getElementById('xs-refresh-state');
let tab='nodes',cache={};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const ago=s=>{if(!s)return 'never';const n=Date.now()-new Date(s).getTime();if(n<60000)return Math.max(0,Math.round(n/1000))+'s ago';if(n<3600000)return Math.round(n/60000)+'m ago';if(n<86400000)return Math.round(n/3600000)+'h ago';return Math.round(n/86400000)+'d ago'};
async function get(url){const r=await fetch(url,{credentials:'same-origin',cache:'no-store'});const t=await r.text();let d={};try{d=t?JSON.parse(t):{}}catch{d={error:t}}if(!r.ok)throw new Error(d.error||`HTTP ${r.status}`);return d;}
async function post(url,body){const r=await fetch(url,{method:'POST',credentials:'same-origin',cache:'no-store',headers:{'Content-Type':'application/json','X-Xavi-Sky-CSRF':CSRF},body:JSON.stringify(body)});const t=await r.text();let d={};try{d=t?JSON.parse(t):{}}catch{d={error:t}}if(!r.ok)throw new Error(d.error||`HTTP ${r.status}`);return d;}
function card(label,value,sub=''){return `<div class="xs-card"><span class="xs-muted">${esc(label)}</span><b>${esc(value)}</b><span class="xs-muted">${esc(sub)}</span></div>`}
async function refresh(all=true){state.textContent='refreshing…';err.innerHTML='';try{cache.status=await get(A.status);cache.accounts=await get(A.accounts);if(all||tab==='nodes')cache.nodes=await get(A.nodes);if(all||tab==='events')cache.events=await get(A.events+'?limit=160');if(all||tab==='packs')cache.packs=await get(A.packs);if(all||tab==='candidates'){const q=document.getElementById('xs-q').value.trim();cache.candidates=await get(A.candidates+'?limit=400'+(q?'&q='+encodeURIComponent(q):''));}renderCards();render();state.textContent='updated '+new Date().toLocaleTimeString();}catch(e){err.innerHTML=`<div class="xs-error">${esc(e.message)}${e.message==='auth'?' — sign in to Xavi first.':''}</div>`;state.textContent='error';}}
function renderCards(){const s=cache.status||{},lr=s.lastRun||{},ac=cache.accounts?.accounts||[];cards.innerHTML=card('Candidates',s.candidateCount??0,'ranked actors')+card('Starter packs',s.starterPackCount??0,'known packs')+card('Federated nodes',s.nodeCount??0,'local replicas')+card('Events',s.eventCount??0,'replicated ledger')+card('Bluesky accounts',ac.length,ac.length?'write-enabled locally':'credentials not configured')+card('Last run',lr.status||'none',lr.finished_at?ago(lr.finished_at):'');}
function render(){if(tab==='nodes')return renderNodes();if(tab==='candidates')return renderCandidates();if(tab==='packs')return renderPacks();return renderEvents();}
function renderNodes(){const rows=cache.nodes?.nodes||[];panel.innerHTML=`<table><thead><tr><th>Node</th><th>Kind</th><th>Version</th><th>Last seen</th><th>Events</th><th>Capabilities</th></tr></thead><tbody>${rows.map(n=>{const live=Date.now()-new Date(n.last_seen_at).getTime()<2*3600000;return `<tr class="${live?'xs-node-live':'xs-node-stale'}"><td>${esc(n.node_id)}</td><td>${esc(n.node_kind)}</td><td>${esc(n.version)}</td><td>${esc(ago(n.last_seen_at))}</td><td>${esc(n.event_count)}</td><td>${esc(n.capabilities_json)}</td></tr>`}).join('')}</tbody></table>`;}
function parseStates(c){try{return JSON.parse(c.account_states||'{}')||{}}catch{return {}}}
function actionButtons(c){const ac=cache.accounts?.accounts||[],st=parseStates(c);if(!ac.length)return '<span class="xs-muted">No local Bluesky credentials configured</span>';return `<div class="xs-actions">${ac.map(a=>{const followed=st[a.handle]==='followed';return `<button class="xs-btn xs-follow" data-account="${esc(a.handle)}" data-did="${esc(c.did)}" ${followed?'disabled':''}>${followed?'Followed':'Follow via '+esc(a.handle)}</button>`}).join('')}</div>`;}
function renderCandidates(){const rows=cache.candidates?.candidates||[];panel.innerHTML=`<table><thead><tr><th>#</th><th>Score</th><th>Account</th><th>Followers</th><th>Posts</th><th>Themes</th><th>Per-account state</th><th>Actions</th></tr></thead><tbody>${rows.map((c,i)=>`<tr><td>${i+1}</td><td class="xs-score">${Number(c.score||0).toFixed(2)}</td><td><b>${esc(c.display_name||c.handle)}</b><br><a class="xs-link" target="_blank" rel="noopener" href="https://bsky.app/profile/${encodeURIComponent(c.handle)}">@${esc(c.handle)}</a><br><span class="xs-muted">${esc(c.did)}</span></td><td>${esc(c.followers_count??'')}</td><td>${esc(c.posts_count??'')}</td><td>${esc(c.themes_json)}</td><td>${esc(c.account_states||'{}')}</td><td>${actionButtons(c)}</td></tr>`).join('')}</tbody></table>`;panel.querySelectorAll('.xs-follow').forEach(b=>b.addEventListener('click',()=>followOne(b)));}
async function followOne(btn){const account=btn.dataset.account,did=btn.dataset.did;if(!account||!did)return;if(!confirm(`Follow ${did} using ${account}?`))return;btn.disabled=true;const old=btn.textContent;btn.textContent='Following…';err.innerHTML='';try{const r=await post(A.follow,{account_handle:account,did});btn.textContent=r.already?'Already followed':'Followed';await refresh(false);}catch(e){btn.disabled=false;btn.textContent=old;err.innerHTML=`<div class="xs-error">Follow failed: ${esc(e.message)}</div>`;}}
function renderPacks(){const rows=cache.packs?.starterPacks||[];panel.innerHTML=`<table><thead><tr><th>Starter pack</th><th>Themes</th><th>First seen</th><th>Last seen</th></tr></thead><tbody>${rows.map(p=>`<tr><td><a class="xs-link" target="_blank" rel="noopener" href="${esc(p.url)}">${esc(p.url)}</a></td><td>${esc(p.themes_json)}</td><td>${esc(ago(p.first_seen_at))}</td><td>${esc(ago(p.last_seen_at))}</td></tr>`).join('')}</tbody></table>`;}
function renderEvents(){const rows=cache.events?.events||[];panel.innerHTML=`<table><thead><tr><th>Seq</th><th>When</th><th>Node</th><th>Event</th><th>Entity</th><th>Account</th><th>Payload</th></tr></thead><tbody>${rows.map(e=>`<tr><td>${esc(e.ingest_seq)}</td><td>${esc(ago(e.created_at))}</td><td>${esc(e.origin_node)}</td><td>${esc(e.event_type)}</td><td>${esc(e.entity_type)}<br><span class="xs-muted">${esc(e.entity_id)}</span></td><td>${esc(e.account_handle||'')}</td><td class="xs-json">${esc(e.payload_json)}</td></tr>`).join('')}</tbody></table>`;}
document.querySelectorAll('.xs-tab').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.xs-tab').forEach(x=>x.classList.remove('on'));b.classList.add('on');tab=b.dataset.tab;refresh(false)}));
document.getElementById('xs-refresh').addEventListener('click',()=>refresh(true));document.getElementById('xs-search').addEventListener('click',()=>{tab='candidates';document.querySelectorAll('.xs-tab').forEach(x=>x.classList.toggle('on',x.dataset.tab==='candidates'));refresh(false)});document.getElementById('xs-q').addEventListener('keydown',e=>{if(e.key==='Enter')document.getElementById('xs-search').click()});
refresh(true);setInterval(()=>refresh(false),30000);
})();
</script>
